return {
    ["Werewolf"] = { fr = "Loup-garou", es = "Hombre lobo", de = "Werwolf" },
    ["Game master for the classic werewolf party game: 6 to 18 players, secret roles, night narration and day votes."] = { fr = "Meneur de jeu pour le loup-garou classique : 6 à 18 joueurs, rôles secrets, narration de la nuit et votes du jour.", es = "Narrador para el clásico juego del hombre lobo: de 6 a 18 jugadores, roles secretos, narración nocturna y votaciones de día.", de = "Spielleiter für das klassische Werwolf-Partyspiel: 6 bis 18 Spieler, geheime Rollen, Erzählung in der Nacht und Abstimmungen am Tag." },
    ["%1 is…"] = { fr = "%1 est…", es = "%1 es…", de = "%1 ist…" },
    ["%1 lowers the rifle and spares everyone."] = { fr = "%1 baisse son fusil et épargne tout le monde.", es = "%1 baja el rifle y perdona a todos.", de = "%1 senkt das Gewehr und verschont alle." },
