    ["Tap a name to rename or remove it."] = { fr = "Touchez un nom pour le modifier ou le supprimer.", es = "Toca un nombre para cambiarlo o quitarlo.", de = "Tippe auf einen Namen, um ihn zu ändern oder zu entfernen." },
    ["Tap the button when nobody else is looking."] = { fr = "Touchez le bouton quand personne d'autre ne regarde.", es = "Toca el botón cuando nadie más mire.", de = "Tippe auf den Knopf, wenn niemand sonst hinschaut." },
    ["The lovers"] = { fr = "Les amoureux", es = "Los enamorados", de = "Die Verliebten" },
    ["The werewolves attacked %1 tonight."] = { fr = "Les loups-garous ont attaqué %1 cette nuit.", es = "Los hombres lobo han atacado a %1 esta noche.", de = "Die Werwölfe haben heute Nacht %1 angegriffen." },
    ["The werewolves attacked nobody tonight."] = { fr = "Les loups-garous n'ont attaqué personne cette nuit.", es = "Los hombres lobo no han atacado a nadie esta noche.", de = "Die Werwölfe haben heute Nacht niemanden angegriffen." },
    ["Theme"] = { fr = "Thème", es = "Tema", de = "Thema" },
    ["Theme: %1"] = { fr = "Thème : %1", es = "Tema: %1", de = "Thema: %1" },
    ["This composition cannot be played. Adjust the roles."] = { fr = "Cette composition n'est pas jouable. Ajustez les rôles.", es = "Esta composición no se puede jugar. Ajusta los roles.", de = "Diese Zusammenstellung ist nicht spielbar. Passe die Rollen an." },
    ["Time's up!"] = { fr = "Temps écoulé !", es = "¡Se acabó el tiempo!", de = "Zeit abgelaufen!" },
    ["Type all names"] = { fr = "Saisir tous les noms", es = "Escribir todos los nombres", de = "Alle Namen eingeben" },
    ["Use your death potion on someone?"] = { fr = "Utiliser votre potion de mort sur quelqu'un ?", es = "¿Usar tu poción de muerte con alguien?", de = "Deinen Todestrank an jemandem einsetzen?" },
    ["Use your healing potion?"] = { fr = "Utiliser votre potion de vie ?", es = "¿Usar tu poción de vida?", de = "Deinen Heiltrank einsetzen?" },
    ["Villagers: %1"] = { fr = "Simples villageois : %1", es = "Aldeanos: %1", de = "Dorfbewohner: %1" },
    ["Vote"] = { fr = "Voter", es = "Votar", de = "Abstimmen" },
    ["Werewolves: %1"] = { fr = "Loups-garous : %1", es = "Hombres lobo: %1", de = "Werwölfe: %1" },
    ["Yes"] = { fr = "Oui", es = "Sí", de = "Ja" },
    ["You may devour one of the werewolves."] = { fr = "Vous pouvez dévorer l'un des loups-garous.", es = "Puedes devorar a uno de los hombres lobo.", de = "Du darfst einen der Werwölfe fressen." },
    ["Your death potion is used up."] = { fr = "Votre potion de mort est déjà utilisée.", es = "Tu poción de muerte ya está usada.", de = "Dein Todestrank ist schon verbraucht." },
    ["Your healing potion is used up."] = { fr = "Votre potion de vie est déjà utilisée.", es = "Tu poción de vida ya está usada.", de = "Dein Heiltrank ist schon verbraucht." },
    ["%1 starts with 2 votes against them (the raven)."] = { fr = "%1 commence avec 2 voix contre (le corbeau).", es = "%1 empieza con 2 votos en contra (el cuervo).", de = "%1 beginnt mit 2 Stimmen gegen sich (der Rabe)." },
    ["%1 was the mayor.\nWith a last breath, they hand the sash to…"] = { fr = "%1 était maire.\nDans un dernier souffle, l'écharpe passe à…", es = "%1 era alcalde.\nCon su último aliento, entrega la banda a…", de = "%1 war Bürgermeister.\nMit letztem Atem geht die Schärpe an…" },
    ["+2 leftover cards for the thief"] = { fr = "+2 cartes restantes pour le voleur", es = "+2 cartas sobrantes para el ladrón", de = "+2 übrige Karten für den Dieb" },
    ["Both leftover cards are werewolves: you must take one."] = { fr = "Les deux cartes restantes sont des loups-garous : vous devez en prendre une.", es = "Las dos cartas sobrantes son hombres lobo: debes coger una.", de = "Beide übrigen Karten sind Werwölfe: du musst eine nehmen." },
    ["Charmed players, open your eyes and look at each other:"] = { fr = "Joueurs charmés, ouvrez les yeux et regardez-vous :", es = "Jugadores hechizados, abrid los ojos y miraos:", de = "Verzauberte, öffnet die Augen und seht euch an:" },
    ["Choose a second victim."] = { fr = "Choisissez une seconde victime.", es = "Elige una segunda víctima.", de = "Wähle ein zweites Opfer." },
    ["Choose two players to charm."] = { fr = "Choisissez deux joueurs à charmer.", es = "Elige dos jugadores para hechizar.", de = "Wähle zwei Spieler zum Verzaubern." },
    ["Choose your role model. If they die, you become a werewolf."] = { fr = "Choisissez votre modèle. S'il meurt, vous devenez loup-garou.", es = "Elige tu modelo. Si muere, te conviertes en hombre lobo.", de = "Wähle dein Vorbild. Stirbt es, wirst du ein Werwolf." },
    ["Devour"] = { fr = "Dévorer", es = "Devorar", de = "Fressen" },
    ["Elect"] = { fr = "Élire", es = "Elegir", de = "Wählen" },
    ["Infect"] = { fr = "Infecter", es = "Infectar", de = "Infizieren" },
    ["Keep none"] = { fr = "N'en garder aucune", es = "No coger ninguna", de = "Keine nehmen" },
    ["Later"] = { fr = "Plus tard", es = "Más tarde", de = "Später" },
    ["Mark a player: they will start the next vote with 2 votes against them."] = { fr = "Marquez un joueur : il commencera le prochain vote avec 2 voix contre lui.", es = "Marca a un jugador: empezará la próxima votación con 2 votos en contra.", de = "Markiere einen Spieler: Er beginnt die nächste Abstimmung mit 2 Stimmen gegen sich." },
    ["Mayor: %1"] = { fr = "Maire : %1", es = "Alcalde: %1", de = "Bürgermeister: %1" },
    ["No werewolf among\n%1.\nYou lose your sense of smell: no more power."] = { fr = "Aucun loup-garou parmi\n%1.\nVous perdez votre flair : plus de pouvoir.", es = "Ningún hombre lobo entre\n%1.\nPierdes el olfato: ya no tienes poder.", de = "Kein Werwolf unter\n%1.\nDu verlierst deinen Riecher: keine Macht mehr." },
    ["Page %1/%2"] = { fr = "Page %1/%2", es = "Página %1/%2", de = "Seite %1/%2" },
    ["Point at a player: you will learn whether a werewolf is among them and their two neighbours."] = { fr = "Désignez un joueur : vous saurez si un loup-garou se trouve parmi lui et ses deux voisins.", es = "Señala a un jugador: sabrás si hay un hombre lobo entre él y sus dos vecinos.", de = "Zeige auf einen Spieler: Du erfährst, ob unter ihm und seinen beiden Nachbarn ein Werwolf ist." },
    ["Sisters, look at each other and agree silently:"] = { fr = "Sœurs, regardez-vous et mettez-vous d'accord en silence :", es = "Hermanas, miraos y poneos de acuerdo en silencio:", de = "Schwestern, seht euch an und einigt euch schweigend:" },
    ["Tap a name to rename or remove it. Enter the players in seating order."] = { fr = "Touchez un nom pour le modifier ou le retirer. Saisissez les joueurs dans l'ordre de la table.", es = "Toca un nombre para cambiarlo o quitarlo. Introduce a los jugadores en el orden de la mesa.", de = "Tippe auf einen Namen, um ihn zu ändern oder zu entfernen. Gib die Spieler in Sitzreihenfolge ein." },
    ["Tap the player elected mayor."] = { fr = "Touchez le joueur élu maire.", es = "Toca al jugador elegido alcalde.", de = "Tippe auf den gewählten Bürgermeister." },
    ["The mayor's vote (%1) counts double."] = { fr = "La voix du maire (%1) compte double.", es = "El voto del alcalde (%1) cuenta doble.", de = "Die Stimme des Bürgermeisters (%1) zählt doppelt." },
    ["The pack chose %1.\nInfect them instead of devouring them? (Once per game.)"] = { fr = "La meute a choisi %1.\nL'infecter au lieu de le dévorer ? (Une fois par partie.)", es = "La manada eligió a %1.\n¿Infectarlo en vez de devorarlo? (Una vez por partida.)", de = "Das Rudel hat %1 gewählt.\nInfizieren statt fressen? (Einmal pro Spiel.)" },
    ["The wolf-father has infected you!\nYou are now a werewolf: from the next night you wake up with the pack, and you win with them. You keep your power."] = { fr = "Le père des loups vous a infecté !\nVous êtes désormais loup-garou : dès la nuit prochaine, vous vous réveillez avec la meute et vous gagnez avec elle. Vous gardez votre pouvoir.", es = "¡El padre de los lobos te ha infectado!\nAhora eres hombre lobo: desde la próxima noche despiertas con la manada y ganas con ella. Conservas tu poder.", de = "Der Wolfsvater hat dich infiziert!\nDu bist jetzt ein Werwolf: Ab der nächsten Nacht wachst du mit dem Rudel auf und gewinnst mit ihm. Deine Fähigkeit behältst du." },
    ["Tie vote"] = { fr = "Égalité", es = "Empate", de = "Gleichstand" },
    ["Two cards are left over. Take one, or keep none and play as a plain villager."] = { fr = "Deux cartes restent. Prenez-en une, ou n'en gardez aucune et jouez simple villageois.", es = "Sobran dos cartas. Coge una o ninguna y juega como simple aldeano.", de = "Zwei Karten sind übrig. Nimm eine, oder keine und spiele als einfacher Dorfbewohner." },
    ["Yes!"] = { fr = "Oui !", es = "¡Sí!", de = "Ja!" },
    ["You are now:"] = { fr = "Vous êtes maintenant :", es = "Ahora eres:", de = "Du bist jetzt:" },
    ["Your nose twitches: there is at least one werewolf among\n%1."] = { fr = "Votre truffe frémit : il y a au moins un loup-garou parmi\n%1.", es = "Tu nariz se mueve: hay al menos un hombre lobo entre\n%1.", de = "Deine Nase zuckt: Unter\n%1\nist mindestens ein Werwolf." },
    ["Medieval"] = { fr = "Médiéval", es = "Medieval", de = "Mittelalter" },
    ["Pirate ship"] = { fr = "Bateau pirate", es = "Barco pirata", de = "Piratenschiff" },
    ["Space station"] = { fr = "Station spatiale", es = "Estación espacial", de = "Raumstation" },
}
